//! Single file enrichment response from Ollama.
//! Contains LLM-generated description and search tags for one file.

use serde::{Deserialize, Serialize};

/// Per-file enrichment data returned by Ollama.
#[derive(Debug, Serialize, Deserialize)]
pub struct OllamaFileEnrichmentResponse {
    /// Unique file identifier matching original FileAnalysis
    pub file_id: String,
    /// LLM-generated description of file purpose
    pub description: String,
    /// Search tags generated by LLM
    pub tags: Vec<String>,
}
